package com.proofclean.analysis.service;
import com.proofclean.analysis.entity.*;import com.proofclean.analysis.repository.MaskedFileRepository;import com.proofclean.common.exception.BadRequestException;import com.proofclean.common.util.ImageUtils;import com.proofclean.config.FileStorageConfig;import lombok.RequiredArgsConstructor;import org.springframework.stereotype.Service;import javax.imageio.ImageIO;import java.awt.*;import java.awt.image.BufferedImage;import java.nio.file.*;import java.util.UUID;
@Service @RequiredArgsConstructor
public class MaskingService { private final FileStorageConfig config; private final MaskedFileRepository maskedFileRepository; public MaskedFile mask(AnalysisProject project, UploadedFile source){ try{ if(!"IMAGE".equals(source.getFileType())) throw new BadRequestException("MVP에서는 이미지 파일만 안전본 생성을 지원합니다."); Files.createDirectories(Path.of(config.maskedDir)); BufferedImage image=ImageIO.read(Path.of(source.getFilePath()).toFile()); Graphics2D g=image.createGraphics(); g.setColor(new Color(15,23,42,210)); for(DetectionFinding f: project.getFindings()){ int x=ImageUtils.clamp((int)(f.getX()*image.getWidth()),0,image.getWidth()); int y=ImageUtils.clamp((int)(f.getY()*image.getHeight()),0,image.getHeight()); int w=ImageUtils.clamp((int)(f.getWidth()*image.getWidth()),1,image.getWidth()-x); int h=ImageUtils.clamp((int)(f.getHeight()*image.getHeight()),1,image.getHeight()-y); g.fillRoundRect(x,y,w,h,16,16); } g.dispose(); String name="masked-"+UUID.randomUUID()+".png"; Path target=Path.of(config.maskedDir).resolve(name); ImageIO.write(image,"png",target.toFile()); return maskedFileRepository.save(MaskedFile.builder().analysisProject(project).sourceFile(source).maskedFileName(name).maskedFilePath(target.toString()).build()); } catch(Exception e){ throw new BadRequestException("안전본 생성에 실패했습니다: "+e.getMessage()); } } }
